#!/usr/bin/bash
#
# Serve qwen3-coder-next-nvfp4 with vLLM on NVIDIA GB10 (Grace-Blackwell, sm_121).
# Canonical, fully-validated serve config (passed all three gates: works / good / fast).
# AUTO-GENERATED by scripts/gen_launcher.sh from runbooks/RedHatAI/Qwen3-Coder-Next-NVFP4/VLLM-23-RedHatAI_Qwen3-Coder-Next_NVFP4_final.sh — do not hand-edit.
#
# Serves the OpenAI-compatible API on http://0.0.0.0:${PORT:-8000}/v1. Weights load from the host
# HF cache ($HF_HOME or ~/.cache/huggingface); set HF_TOKEN to pull on first run. Runs DETACHED:
#   docker logs -f <NAME>   # follow startup/serving logs    (NAME defaults below)
#   docker rm -f  <NAME>    # stop + remove the container
#   PORT=8001 NAME=foo ./VLLM-23-RedHatAI_Qwen3-Coder-Next_NVFP4.sh   # override the published port / container name
#

# Upstream vLLM v0.23.0 pinned by digest for reproducibility — the release tag is already immutable;
# the digest makes it byte-exact. Blackwell kernels are built sm_120 (forward-compatible to the
# GB10's sm_121); FlashInfer JITs the FP4/MoE paths for the device at runtime.
export VLLM_IMAGE="vllm/vllm-openai@sha256:6d8429e38e3747723ca07ee1b17972e09bb9c51c4032b266f24fb1cc3b22ed8f"  # v0.23.0
export MODEL="RedHatAI/Qwen3-Coder-Next-NVFP4"
export MODEL_REVISION="27a8f16f463b9a13c91c332c40cf93e09717347e"   # pinned for reproducibility

# Validated serving context (the benchmark shape). Lower it to raise the guaranteed concurrency
# floor; raise toward the model's native context for long-context serving (KV pool = util below).
export MAX_MODEL_LEN=8192

NAME="${NAME:-vllm-qwen3-coder-next-nvfp4}"
PORT="${PORT:-8000}"
HF_CACHE="${HF_HOME:-$HOME/.cache/huggingface}"

# Replace any prior container of this name.
docker rm -f "${NAME}" 2>/dev/null || true

docker run -d --name "${NAME}" \
	--gpus all \
	--ipc=host \
	-p "${PORT}:8000" \
	-v "${HF_CACHE}:/root/.cache/huggingface" \
	-e TOKENIZERS_PARALLELISM=false \
	-e "HF_TOKEN=${HF_TOKEN:-}" \
	"${VLLM_IMAGE}" \
		"${MODEL}" \
		--served-model-name qwen3-coder-next-nvfp4 \
		--revision "${MODEL_REVISION}" \
		--max-model-len "${MAX_MODEL_LEN}" \
		--tensor-parallel-size 1 \
		--gpu-memory-utilization 0.5 \
		--override-generation-config '{"top_p":0.95,"top_k":40}' \
		--enable-auto-tool-choice \
		--tool-call-parser qwen3_coder
